local OilLampMaker = {}
local PRODUCTS = {
    simple_clay_oil_lamp = { name = "Preprosta glinena oljna svetilka", clayCost = 2, oilCost = 1, time = 3, cost = 40, lightRadius = 20, happiness = 1, description = "Preprosta glinena oljna svetilka za razsvetljavo." },
    brass_oil_lamp = { name = "Medeninasta oljna svetilka", brassCost = 2, clayCost = 1, oilCost = 1, time = 5, cost = 110, lightRadius = 32, happiness = 1, prestige = 2, description = "Medeninasta oljna svetilka za trgovce." },
    silver_trimmed_oil_lamp = { name = "Srebrnoobrobljena oljna svetilka", silverCost = 1, brassCost = 2, clayCost = 1, oilCost = 1, time = 8, cost = 280, lightRadius = 45, happiness = 2, prestige = 6, description = "Srebrnoobrobljena oljna svetilka za plemiče." },
    gold_trimmed_oil_lamp = { name = "Zlatookrasna oljna svetilka", goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, oilCost = 1, time = 12, cost = 680, lightRadius = 58, happiness = 3, prestige = 14, description = "Zlatookrasna oljna svetilka za visoke plemiče." },
    jewel_set_oil_lamp = { name = "Draguljasta oljna svetilka", goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, oilCost = 1, jewelCost = 1, time = 16, cost = 1500, lightRadius = 72, happiness = 5, prestige = 27, description = "Oljna svetilka z draguljem za visoko plemstvo." },
    royal_grand_oil_lamp = { name = "Kraljevski veliki oljna svetilka", goldCost = 2, silverCost = 2, brassCost = 2, clayCost = 1, oilCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3500, lightRadius = 90, happiness = 12, prestige = 58, description = "Velika kraljevska oljna svetilka z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    oil_lamp_workshop = { name = "Oljna svetilkarska delavnica", cost = { gold = 240, wood = 100, stone = 120, clay = 6, oil = 6 }, upkeep = 5, qualityBonus = 5 },
    lighting_loft = { name = "Razsvetljena podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    master_lamp_atelier = { name = "Mojstrski svetilkarski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_lighting_palace = { name = "Kraljevska razsvetljenska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
OilLampMaker.clayStock = 14; OilLampMaker.oilStock = 10; OilLampMaker.brassStock = 12; OilLampMaker.silverStock = 6; OilLampMaker.goldStock = 6; OilLampMaker.jewelStock = 4; OilLampMaker.pearlStock = 4
OilLampMaker.productStock = {}; OilLampMaker.buildings = {}; OilLampMaker.maker = nil; OilLampMaker.activeMaking = {}; OilLampMaker.totalProducts = 0; OilLampMaker.dayTimer = 0
function OilLampMaker.init() OilLampMaker.clayStock=14; OilLampMaker.oilStock=10; OilLampMaker.brassStock=12; OilLampMaker.silverStock=6; OilLampMaker.goldStock=6; OilLampMaker.jewelStock=4; OilLampMaker.pearlStock=4; OilLampMaker.productStock={}; OilLampMaker.buildings={}; OilLampMaker.maker=nil; OilLampMaker.activeMaking={}; OilLampMaker.totalProducts=0; OilLampMaker.dayTimer=0; print("[OilLampMaker] Royal Oil Lamp Maker System initialized (6 products, 4 buildings)") end
function OilLampMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OilLampMaker.maker={name=n or ("Svetilkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilkar najet: %s (spretnost: %d)",OilLampMaker.maker.name,s),"success") end; return true end
function OilLampMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OilLampMaker.build(id) local ok,e=OilLampMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OilLampMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OilLampMaker.getQualityBonus() local b=0; for _,bd in ipairs(OilLampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OilLampMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and OilLampMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.oilCost and OilLampMaker.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.brassCost and OilLampMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and OilLampMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OilLampMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OilLampMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and OilLampMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #OilLampMaker.buildings==0 then return false,"Potrebna oljna svetilkarska delavnica" end; if not OilLampMaker.maker then return false,"Potreben svetilkar" end; return true end
function OilLampMaker.make(pt,qty) qty=qty or 1; local ok,e=OilLampMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then OilLampMaker.clayStock=OilLampMaker.clayStock-d.clayCost*qty end; if d.oilCost then OilLampMaker.oilStock=OilLampMaker.oilStock-d.oilCost*qty end; if d.brassCost then OilLampMaker.brassStock=OilLampMaker.brassStock-d.brassCost*qty end; if d.silverCost then OilLampMaker.silverStock=OilLampMaker.silverStock-d.silverCost*qty end; if d.goldCost then OilLampMaker.goldStock=OilLampMaker.goldStock-d.goldCost*qty end; if d.jewelCost then OilLampMaker.jewelStock=OilLampMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then OilLampMaker.pearlStock=OilLampMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if OilLampMaker.maker then t=math.max(1,t-math.floor(OilLampMaker.maker.skill/13)) end; table.insert(OilLampMaker.activeMaking,{id="oillamp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightRadius=d.lightRadius or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OilLampMaker.completeMaking(m) local q=1.0+(OilLampMaker.getQualityBonus()/100); if OilLampMaker.maker then q=q+(OilLampMaker.maker.skill/140) end; q=math.min(2.5,q); OilLampMaker.productStock[m.productType]=(OilLampMaker.productStock[m.productType] or 0)+m.quantity; OilLampMaker.totalProducts=OilLampMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OilLampMaker.maker then OilLampMaker.maker.itemsMade=OilLampMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then OilLampMaker.maker.skill=math.min(100,OilLampMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oljna svetilka izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"oillamp.completed",{productName=m.productName,lightRadius=m.lightRadius,prestige=m.prestige,happiness=m.happiness}) end end
function OilLampMaker.update(dt) if not _G.state then return end; OilLampMaker.dayTimer=OilLampMaker.dayTimer+dt; if OilLampMaker.dayTimer>=30 then OilLampMaker.dayTimer=0; for i=#OilLampMaker.activeMaking,1,-1 do local m=OilLampMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OilLampMaker.completeMaking(m); table.remove(OilLampMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OilLampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OilLampMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OilLampMaker.getStats() return {clayStock=OilLampMaker.clayStock,oilStock=OilLampMaker.oilStock,brassStock=OilLampMaker.brassStock,silverStock=OilLampMaker.silverStock,goldStock=OilLampMaker.goldStock,jewelStock=OilLampMaker.jewelStock,pearlStock=OilLampMaker.pearlStock,productStock=OilLampMaker.productStock,numBuildings=#OilLampMaker.buildings,hasMaker=OilLampMaker.maker~=nil,makerName=OilLampMaker.maker and OilLampMaker.maker.name or "—",makerSkill=OilLampMaker.maker and OilLampMaker.maker.skill or 0,activeMaking=#OilLampMaker.activeMaking,totalProducts=OilLampMaker.totalProducts} end
return OilLampMaker
